mkdir -p /tmp/va && cat > /tmp/va/r.py <<'EOF'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None;stats={"retries":0,"401":0,"429":0,"other":[]}
def newtok():
    global tok
    tok=json.load(urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST",data=b"")))["token"]
def get(p):
    global tok
    for a in range(200):
        if tok is None: 
            try: newtok()
            except Exception as e: time.sleep(1); continue
        r=urllib.request.Request(B+p,headers={"Authorization":"Bearer "+tok})
        try: return json.load(urllib.request.urlopen(r,timeout=30))
        except urllib.error.HTTPError as e:
            if e.code==401: stats["401"]+=1; tok=None; continue
            if e.code==429:
                stats["429"]+=1; w=e.headers.get("Retry-After") or "1"
                try: w=float(w)
                except: w=1
                time.sleep(w); continue
            if e.code==404 and p.startswith("/customers"): return None
            stats["other"].append(e.code); time.sleep(0.5)
        except Exception as e: stats["other"].append(str(e)[:40]); time.sleep(0.5)
    raise SystemExit("fail "+p)
seen={};dups=0;p="/orders?page=1";pages=0;tp=None
while p:
    d=get(p);pages+=1;tp=d["total_pages"]
    for o in d["items"]:
        if o["id"] in seen: dups+=1
        else: seen[o["id"]]=o
    p=d["next"]
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={k:0 for k in["north","south","east","west"]};n=0;odd=[]
for o in seen.values():
    if o["status"]!="shipped": continue
    s=o["placed_at"].replace("Z","+00:00");t=datetime.fromisoformat(s)
    if t.tzinfo is None: odd.append(("naive",o["id"])); t=t.replace(tzinfo=timezone.utc)
    t=t.astimezone(timezone.utc)
    if not(lo<=t<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    cu=cust[c]
    if cu is None: odd.append(("nocust",o["id"],c)); continue
    v=(o["amount_cents"]*(100-cu["discount_pct"])*2+100)//200
    reg[cu["region"]]+=v;n+=1
json.dump({"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg},open("/workspace/result.json","w"),indent=2)
print(pages,tp,len(seen),stats["401"],stats["429"],stats["other"][:10],odd[:10],len(odd))
print(set(o["status"] for o in seen.values()))
EOF
python3 -I /tmp/va/r.py; cat /workspace/result.json

